'use client'

import { cn } from '@gentleduck/libs/cn'
import { loadDomAnimation } from '@gentleduck/motion/motion-features'
import { springBouncy } from '@gentleduck/motion/transitions/springs'
import { checkersStylePattern } from '@gentleduck/motion/variants'
import { useSvgIndicator } from '@gentleduck/primitives/checkers'
import { type Direction, useDirection } from '@gentleduck/primitives/direction'
import { LazyMotion, m } from 'motion/react'
import * as React from 'react'

const Switch = React.forwardRef<
  HTMLInputElement,
  Omit<React.HTMLProps<HTMLInputElement>, 'ref'> & {
    indicator?: React.ReactElement
    checkedIndicator?: React.ReactElement
    onCheckedChange?: (checked: boolean) => void
  }
>(({ className, indicator, checkedIndicator, onChange, onCheckedChange, dir, style, ...props }, ref) => {
  const direction = useDirection(dir as Direction)
  const { indicatorReady, checkedIndicatorReady, inputStyle, SvgIndicator } = useSvgIndicator({
    checkedIndicator,
    indicator,
  })

  return (
    <>
      <input
        className={cn(
          checkersStylePattern({
            indicatorState:
              indicatorReady && checkedIndicatorReady
                ? 'both'
                : indicatorReady
                  ? 'indicatorReady'
                  : checkedIndicatorReady
                    ? 'checkedIndicatorReady'
                    : 'default',
            type: 'switch',
          }),
          'transition-all transition-discrete duration-[200ms,150ms] ease-(--duck-motion-ease)',
          '[&:before,&:after]:transition-gpu [&:before,&:after]:duration-[inherit] [&:before,&:after]:ease-[inherit] [&:before,&:after]:will-change-[inherit]',
          '[&[dir=ltr]:checked]:after:translate-x-full [&[dir=ltr]]:after:translate-x-0',
          '[&[dir=rtl]:checked]:after:-translate-x-full [&[dir=rtl]]:after:translate-x-0',
          '[&:not(:checked)]:after:origin-right [&:checked]:after:origin-left',
          'active:after:scale-x-125 active:after:scale-y-110',
          className,
        )}
        onChange={(e) => {
          onChange?.(e)
          onCheckedChange?.(e.target.checked)
        }}
        aria-checked={props.checked}
        ref={ref}
        role="switch"
        dir={direction}
        style={{ ...style, ...inputStyle }}
        type="checkbox"
        {...props}
        data-slot="switch"
      />
      <SvgIndicator className="sr-only" />
    </>
  )
})
Switch.displayName = 'Switch'

const MotionSwitch = React.forwardRef<
  HTMLInputElement,
  Omit<React.HTMLProps<HTMLInputElement>, 'ref' | 'onDrag' | 'onDragStart' | 'onDragEnd' | 'onAnimationStart'> & {
    onCheckedChange?: (checked: boolean) => void
  }
>(({ className, onCheckedChange, onChange, checked, defaultChecked, dir, disabled, style, ...props }, ref) => {
  const direction = useDirection(dir as Direction)
  const isRtl = direction === 'rtl'
  const isControlled = checked !== undefined
  const [internalChecked, setInternalChecked] = React.useState<boolean>(defaultChecked ?? false)
  const value = isControlled ? (checked ?? false) : internalChecked
  const [pressed, setPressed] = React.useState(false)

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!isControlled) setInternalChecked(e.target.checked)
    onChange?.(e)
    onCheckedChange?.(e.target.checked)
  }

  const releasePress = () => setPressed(false)

  // Stretch direction: the thumb pulls toward where it's about to travel so
  // the squish reads as "about to launch". Unchecked -> growing right,
  // checked -> growing left (inverted in RTL).
  const stretchOrigin = !value ? (isRtl ? 'right center' : 'left center') : isRtl ? 'left center' : 'right center'

  return (
    <LazyMotion features={loadDomAnimation}>
      <m.label
        dir={direction}
        data-slot="switch"
        data-state={value ? 'checked' : 'unchecked'}
        className={cn(
          'relative inline-flex h-[1.75em] w-[3em] shrink-0 cursor-pointer items-center rounded-full border p-[0.125em]',
          'ring-offset-background focus-within:outline-hidden focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2',
          disabled && 'pointer-events-none cursor-not-allowed opacity-50',
          className,
        )}
        style={style}
        initial={false}
        animate={{
          backgroundColor: value ? 'var(--primary)' : 'var(--border)',
          borderColor: value ? 'var(--primary)' : 'var(--border)',
        }}
        transition={{ duration: 0.22, ease: [0.16, 1, 0.3, 1] }}
        whileTap={disabled ? undefined : { scale: 0.97 }}
        onPointerDown={disabled ? undefined : () => setPressed(true)}
        onPointerUp={releasePress}
        onPointerLeave={releasePress}
        onPointerCancel={releasePress}>
        <input
          ref={ref}
          type="checkbox"
          role="switch"
          aria-checked={value}
          dir={direction}
          disabled={disabled}
          checked={isControlled ? value : undefined}
          defaultChecked={!isControlled ? defaultChecked : undefined}
          onChange={handleChange}
          className="absolute inset-0 size-full cursor-pointer opacity-0 disabled:cursor-not-allowed"
          {...props}
        />
        <m.span
          aria-hidden="true"
          className="pointer-events-none block size-[1.375em] rounded-full bg-background shadow-sm"
          style={{ transformOrigin: stretchOrigin }}
          animate={{
            x: value ? (isRtl ? '-1.25em' : '1.25em') : '0em',
            scaleX: pressed ? 1.3 : 1,
            scaleY: pressed ? 0.92 : 1,
          }}
          transition={{
            x: { ...springBouncy, mass: 0.6 },
            scaleX: { type: 'tween', duration: 0.12, ease: 'easeOut' },
            scaleY: { type: 'tween', duration: 0.12, ease: 'easeOut' },
          }}
        />
      </m.label>
    </LazyMotion>
  )
})
MotionSwitch.displayName = 'MotionSwitch'

export { MotionSwitch, Switch }
